#!/usr/bin/env node
/**
 * Zero-Dependency Desktop Plugin Bundler
 *
 * Stitches modular source files in `desktop/src/` into the single-file
 * runtime distribution `desktop/plugin.js` for Hermes Desktop.
 *
 * Dependencies: Node.js standard library only (node:fs, node:path).
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const OUT_FILE = path.resolve(ROOT, 'desktop/plugin.js');

const MODULE_ORDER = [
	'desktop/src/data/constants.js',
	'desktop/src/data/fallbacks.js',
	'desktop/src/services/host-bridge.js',
	'desktop/src/services/search-service.js',
	'desktop/src/hooks/useDebouncedValue.js',
	'desktop/src/components/GlyphSpinner.js',
	'desktop/src/components/SymbolInspectorDetail.js',
	'desktop/src/components/InlineAppleDocCard.js',
	'desktop/src/views/status/AppleDocsStatusChip.js',
	'desktop/src/views/panes/AppleDocsCompilerPane.js',
	'desktop/src/views/panes/AppleDocsSidePane.js',
	'desktop/src/views/studio/AppleDocsStudioPage.js',
	'desktop/src/contributions/register.js',
	'desktop/src/index.js',
];

const HEADER = `/**
 * Apple Developer Documentation Studio — Hermes Desktop Plugin (\`desktop/plugin.js\`).
 *
 * Surfaces contributed strictly via \`@hermes/plugin-sdk\`:
 *  1. Workspace Page (\`ROUTES_AREA\`: \`/apple-docs\`) + Sidebar Nav (\`SIDEBAR_NAV_AREA\`)
 *     - 95.9k Symbol & DocC Explorer
 *     - Cross-Framework Idiom Rosetta Stone (React / Web CSS / Android Kotlin -> SwiftUI & Swift 6)
 *     - Swift / Xcode Compiler Diagnostic Grounding Lab (live simulator for \`transform_terminal_output\`)
 *     - 30-Framework Index Coverage & 1-Click Judge Showcase
 *  2. Dockable Right Inspector Pane (\`PANES_AREA\`: quick Apple API lookup beside chat)
 *  3. Inline Transcript Directive (\`TRANSCRIPT_DIRECTIVE_AREA\`: \`::apple-doc{...}\` rich API cards in chat)
 *  4. Statusbar Readiness Chip (\`STATUSBAR_AREAS.right\`) + Command Palette (\`PALETTE_AREA\`)
 *
 * NOTE: Generated by \`node scripts/bundle-desktop.js\` from \`desktop/src/\`.
 * Zero build-step dependencies required.
 */

import { useEffect, useMemo, useState } from 'react';
import { Fragment, jsx, jsxs } from 'react/jsx-runtime';
import {
	Badge,
	Button,
	Codicon,
	CopyButton,
	EmptyState,
	GlyphSpinner as SdkGlyphSpinner,
	haptic,
	host,
	PALETTE_AREA,
	PANES_AREA,
	ROUTES_AREA,
	RowButton,
	ScrollArea,
	SearchField,
	SegmentedControl,
	Select,
	SelectContent,
	SelectItem,
	SelectTrigger,
	SelectValue,
	Separator,
	SIDEBAR_NAV_AREA,
	STATUSBAR_AREAS,
	StatusDot,
	Tabs,
	TabsList,
	TabsTrigger,
	Textarea,
	Tip,
	TRANSCRIPT_DIRECTIVE_AREA,
	useMutation,
	usePluginI18n,
	useQuery,
} from '@hermes/plugin-sdk';
`;

function transformModule(filePath) {
	let code = fs.readFileSync(path.resolve(ROOT, filePath), 'utf8');

	// Strip single-line or multi-line imports
	code = code.replace(/import\s+[\s\S]*?\s+from\s+['"][^'"]+['"];?\n?/g, '');

	// Strip export statements from declarations, keeping the declaration itself
	// e.g. export const X = ... -> const X = ...
	// e.g. export function X(...) -> function X(...)
	// e.g. export async function X(...) -> async function X(...)
	// Keep "export default" as is.
	code = code.replace(
		/^export\s+(const|let|var|function|async function|class)\b/gm,
		'$1',
	);

	// Strip named export blocks e.g. export { ... };
	code = code.replace(/^export\s*\{[\s\S]*?\};?\n?/gm, '');

	// Clean up leading/trailing whitespace
	return code.trim();
}

function bundle() {
	const parts = [HEADER.trim()];

	for (const modPath of MODULE_ORDER) {
		const transformed = transformModule(modPath);
		if (transformed) {
			parts.push(`// --- ${modPath} ---`);
			parts.push(transformed);
		}
	}

	const result = parts.join('\n\n') + '\n';
	fs.writeFileSync(OUT_FILE, result, 'utf8');
	console.log(
		`[bundle-desktop] Built ${OUT_FILE} (${(result.length / 1024).toFixed(1)} KB) with 0 external dependencies.`,
	);
}

bundle();
